package main

import (
  "net/http"
  "github.com/gin-gonic/gin"
)

func main() {
  r := gin.New()
  r.GET("/healthz", func(c *gin.Context) { c.String(http.StatusOK, "ready\n") })
  r.GET("/", func(c *gin.Context) { c.String(http.StatusOK, "catalog gin\n") })
  _ = r.Run(":8080")
}

package main

import (
  "fmt"
  "net/http"
)

func main() {
  mux := http.NewServeMux()
  mux.HandleFunc("/healthz", func(w http.ResponseWriter, _ *http.Request) { fmt.Fprint(w, "ready\n") })
  mux.HandleFunc("/", func(w http.ResponseWriter, _ *http.Request) { fmt.Fprint(w, "catalog go\n") })
  _ = http.ListenAndServe(":8080", mux)
}

